\Rightarrow \tan^{-1} \frac{7}{11} + \tan^{-1} \frac{1}{5} + \tan^{-1} \left(\frac{1}{n}\right) = \frac{\pi}{4}
\Rightarrow \tan^{-1} \left(\frac{\frac{7}{11} + \frac{1}{5}}{1 - \frac{7}{11}.\frac{1}{5}}\right) + \tan^{-1} \left(\frac{1}{n}\right) = \frac{\pi}{4}
\Rightarrow \tan^{-1} \left(\frac{\frac{35+11}{55}}{\frac{55-7}{11.5}}\right) + \tan^{-1} \left(\frac{1}{n}\right) = \frac{\pi}{4}
\Rightarrow \tan^{-1} \left(\frac{\frac{23}{24} + \frac{1}{n}}{1 - \frac{23}{24} \frac{1}{n}}\right) = \frac{\pi}{4}
\Rightarrow \tan^{-1} \left(\frac{23n + 24}{24n - 23}\right) = \frac{\pi}{4}
\Rightarrow 23n + 24 = 24n - 23
\Rightarrow n = 47

